package com.bank.signaturemanagement.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="employee_media_requests") public class EmployeeMediaRequest{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="employee_id")private Employee employee;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="submitted_by")private User submittedBy;
 @Column(name="photo_path")private String photoPath;@Column(name="local_signature_path")private String localSignaturePath;@Column(name="foreign_signature_path")private String foreignSignaturePath;@Column(nullable=false)private String status="PENDING_DGM";@Column(name="submitted_at",insertable=false,updatable=false)private LocalDateTime submittedAt;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="dgm_approver")private User dgmApprover;@Column(name="dgm_decided_at")private LocalDateTime dgmDecidedAt;@Column(name="dgm_remarks")private String dgmRemarks;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="gm_approver")private User gmApprover;@Column(name="gm_decided_at")private LocalDateTime gmDecidedAt;@Column(name="gm_remarks")private String gmRemarks;@Column(name="rejection_remarks")private String rejectionRemarks;
 public Long getId(){return id;}public Employee getEmployee(){return employee;}public void setEmployee(Employee v){employee=v;}public User getSubmittedBy(){return submittedBy;}public void setSubmittedBy(User v){submittedBy=v;}public String getPhotoPath(){return photoPath;}public void setPhotoPath(String v){photoPath=v;}public String getLocalSignaturePath(){return localSignaturePath;}public void setLocalSignaturePath(String v){localSignaturePath=v;}public String getForeignSignaturePath(){return foreignSignaturePath;}public void setForeignSignaturePath(String v){foreignSignaturePath=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public LocalDateTime getSubmittedAt(){return submittedAt;}public User getDgmApprover(){return dgmApprover;}public void setDgmApprover(User v){dgmApprover=v;}public void setDgmDecidedAt(LocalDateTime v){dgmDecidedAt=v;}public String getDgmRemarks(){return dgmRemarks;}public void setDgmRemarks(String v){dgmRemarks=v;}public void setGmApprover(User v){gmApprover=v;}public void setGmDecidedAt(LocalDateTime v){gmDecidedAt=v;}public void setGmRemarks(String v){gmRemarks=v;}public void setRejectionRemarks(String v){rejectionRemarks=v;}
}
